async function generateContent(topic) {
  const prompt = `You are a social media expert.
Topic: ${topic}
Return exactly 5 hashtags and 1 caption.
Format as JSON: {"hashtags": [...], "caption": "..."}` ;

  const response = await anthropic.messages.create({
    model: 'claude-sonnet-4-20250514',
    max_tokens: 500,
    messages: [{ role: 'user', content: prompt }]
  });

  return JSON.parse(response.content[0].text);
}

app.post('/generate', async (req, res) => {
  const { topic } = req.body;

  if (!topic) {
    return res.status(400).json({ error: 'Topic required' });
  }

  try {
    const result = await generateContent(topic);
    res.json(result);
  } catch (error) {
    res.status(500).json({ error: 'Generation failed' });
  }
});

document.getElementById('generateBtn').addEventListener('click', async () => {
  const topic = document.getElementById('topicInput').value;

  const response = await fetch('/generate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ topic })
  });

  const data = await response.json();

  // Display hashtags
  const hashtagList = document.getElementById('hashtags');
  hashtagList.innerHTML = data.hashtags.map(tag => `<li>${tag}</li>`).join('');

  // Display caption
  document.getElementById('caption').textContent = data.caption;
});
